    --text-faint: #647280;
    --accent: #e8934a;
    --accent-soft: #3a2e20;
    --accent-2: #6cc4b1;
    --accent-2-soft: #1c3530;
    --danger: #e2726a;
    --danger-soft: #3a2321;
    --code-bg: #12171c;
    --code-border: #2a3441;
    --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 8px 24px rgba(0, 0, 0, 0.35);
  }

  * { box-sizing: border-box; }

  body {
