  }
  .toc a:hover, .toc a:focus-visible { background: var(--surface-2); color: var(--text); outline: none; }
  .toc .num { font-family: var(--font-mono); font-size: 0.7rem; color: var(--text-faint); min-width: 1.3rem; }

  .toc-phase {
