  .sidebar-meta strong { color: var(--text-dim); font-weight: 600; }

  /* ---------- Main column ---------- */

  main { padding: 2.5rem 3rem 6rem; min-width: 0; }

  header.hero {
    margin-bottom: 2.75rem;
    padding-bottom: 2rem;
