  }
  .eyebrow::before {
    content: "";
    width: 7px; height: 7px; border-radius: 50%;
    background: var(--danger);
    flex-shrink: 0;
  }

  h1 {
    font-family: var(--font-display);
    font-weight: 700;
    font-size: clamp(2.1rem, 4vw, 2.85rem);
