  .phase h2 {
    font-family: var(--font-display);
    font-weight: 700;
    font-size: 1.7rem;
    margin: 0;
    letter-spacing: -0.008em;
  }
  .phase-intro {
    font-family: var(--font-ui);
    color: var(--text-dim);
    font-size: 0.97rem;
