  section { margin-bottom: 2.6rem; scroll-margin-top: 1.5rem; }
  section:last-child { margin-bottom: 0; }

  .section-head {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    margin-bottom: 1.1rem;
  }
  .section-num {
    font-family: var(--font-mono);
    font-size: 0.95rem;
