  }
  h3.section-title {
    font-family: var(--font-display);
    font-weight: 700;
    font-size: 1.32rem;
    margin: 0;
    letter-spacing: -0.005em;
  }

  p { max-width: 68ch; margin: 0 0 1.1rem; }
  p:last-child { margin-bottom: 0; }

  code, .inline-code {
    font-family: var(--font-mono);
    font-size: 0.87em;
    background: var(--code-bg);
