  .problem-row:first-of-type { border-top: none; padding-top: 0; }
  .problem-label {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding-top: 0.2rem;
