  .problem-row.symptom .problem-label { color: var(--danger); }
  .problem-row.cause .problem-label { color: var(--text-faint); }
  .problem-row.fix .problem-label { color: var(--accent-2); }
  .problem-row p, .problem-row pre { font-family: var(--font-ui); font-size: 0.91rem; margin: 0; }
  .problem-row pre { font-family: var(--font-mono); margin-top: 0.4rem; }
  .problem-row + .problem-row { margin-top: 0; }

  /* ---------- Checklist ---------- */

  .checklist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.7rem; }
  .checklist li {
    font-family: var(--font-ui);
    font-size: 0.94rem;
    color: var(--text);
    display: flex;
    gap: 0.7rem;
    align-items: baseline;
  }
  .checklist li::before {
    content: "";
    flex-shrink: 0;
    width: 0.85rem; height: 0.85rem;
    margin-top: 0.2rem;
    border: 1.5px solid var(--text-faint);
    border-radius: 3px;
  }
  .checklist .why { color: var(--text-dim); font-size: 0.88rem; display: block; margin-top: 0.15rem; }

  .steps { list-style: none; margin: 0; padding: 0; counter-reset: step; display: flex; flex-direction: column; gap: 1.3rem; }
  .steps > li {
    counter-increment: step;
    position: relative;
    padding-left: 2.6rem;
  }
  .steps > li::before {
    content: counter(step);
    position: absolute;
    left: 0; top: 0.05rem;
    width: 1.9rem; height: 1.9rem;
    border-radius: 50%;
    background: var(--surface-2);
    border: 1px solid var(--border);
    color: var(--text-dim);
    font-family: var(--font-mono);
    font-weight: 600;
    font-size: 0.85rem;
    display: flex; align-items: center; justify-content: center;
  }
  .steps > li > .step-title {
    font-family: var(--font-ui);
    font-weight: 600;
    color: var(--text);
    margin: 0 0 0.35rem;
    font-size: 0.98rem;
  }
  .steps > li p { margin-bottom: 0.6rem; }
  .steps > li > *:last-child { margin-bottom: 0; }

  .steps.migration > li::before { background: var(--accent-2-soft); border-color: var(--accent-2); color: var(--accent-2); }
  .steps.detect > li::before { background: var(--surface); }

  .note {
    font-family: var(--font-ui);
    font-size: 0.86rem;
    color: var(--text-dim);
    background: var(--surface-2);
    border-radius: 6px;
    padding: 0.65rem 0.85rem;
    margin-top: 0.6rem;
  }
  .note strong { color: var(--text); }

  .callout {
    border-radius: 10px;
    padding: 1.4rem 1.6rem;
    margin: 1.25rem 0;
    border: 1px solid var(--border);
  }
  .callout-principle {
    background: linear-gradient(180deg, var(--accent-2-soft), transparent 140%);
    border-color: color-mix(in srgb, var(--accent-2) 35%, var(--border));
  }
  .callout-gap {
    background: linear-gradient(180deg, var(--danger-soft), transparent 140%);
    border-color: color-mix(in srgb, var(--danger) 35%, var(--border));
  }
  .callout-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 0.6rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }
  .callout-principle .callout-label { color: var(--accent-2); }
  .callout-gap .callout-label { color: var(--danger); }
  .callout p { font-family: var(--font-ui); font-size: 0.95rem; margin-bottom: 0.75rem; }
  .callout p:last-child { margin-bottom: 0; }

  .principle-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 1rem; }
  .principle-list li {
    display: grid;
    grid-template-columns: 1.6rem minmax(0, 1fr);
    gap: 0.9rem;
  }
  .principle-list .mark {
    font-family: var(--font-display);
    font-weight: 700;
    color: var(--accent-2);
    font-size: 1.1rem;
  }
  .principle-list p { font-family: var(--font-ui); font-size: 0.95rem; margin: 0; }
  .principle-list strong { color: var(--text); }

  .compare {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin: 1.1rem 0;
  }
  .compare-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 1rem 1.15rem;
  }
  .compare-card.no { border-left: 3px solid var(--danger); }
  .compare-card.yes { border-left: 3px solid var(--accent-2); }
  .compare-card h4 {
    font-family: var(--font-ui);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin: 0 0 0.5rem;
  }
  .compare-card.no h4 { color: var(--danger); }
  .compare-card.yes h4 { color: var(--accent-2); }
  .compare-card p { font-family: var(--font-ui); font-size: 0.88rem; margin: 0; color: var(--text-dim); }

  .field-table {
    width: 100%;
    border-collapse: collapse;
    font-family: var(--font-ui);
    font-size: 0.88rem;
    margin: 1rem 0;
  }
  .field-table th, .field-table td {
    text-align: left;
    padding: 0.55rem 0.8rem;
    border-bottom: 1px solid var(--border);
  }
  .field-table th {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--text-faint);
    font-weight: 600;
  }
  .field-table td.mono { font-family: var(--font-mono); font-size: 0.85rem; }
  .field-table tr:last-child td { border-bottom: none; }
  .table-wrap { overflow-x: auto; }

  .gaplist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 1.1rem; }
  .gaplist li { font-family: var(--font-ui); font-size: 0.93rem; }
  .gaplist code { font-size: 0.85em; }

  footer {
    margin-top: 3.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--border);
    font-family: var(--font-ui);
    font-size: 0.82rem;
    color: var(--text-faint);
  }

  @media (max-width: 880px) {
    .shell { grid-template-columns: 1fr; }
    .sidebar { position: relative; height: auto; border-right: none; border-bottom: 1px solid var(--border); }
    main { padding: 2rem 1.25rem 4rem; }
    .compare { grid-template-columns: 1fr 1fr; }
    .problem-row { grid-template-columns: 5.2rem minmax(0, 1fr); }
  }
  @media (max-width: 620px) {
    .compare { grid-template-columns: 1fr; }
    .problem-row { grid-template-columns: 1fr; gap: 0.2rem; }
  }

  @media (prefers-reduced-motion: no-preference) {
    .phase { animation: rise 0.5s ease both; }
    @keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
  }
</style>

